-- Generated by tools/generate-database.py; fictional data only.

CREATE TABLE VD_SCHEMA_VERSION (
    VERSION_NO NUMBER(19,0) PRIMARY KEY
);

CREATE TABLE VD_COUNTER (
    KEY_NAME VARCHAR2(30 CHAR) PRIMARY KEY,
    NEXT_VAL NUMBER(19,0) NOT NULL
);

CREATE TABLE VD_SITE (
    ID VARCHAR2(30 CHAR) PRIMARY KEY,
    NAME VARCHAR2(200 CHAR) NOT NULL,
    SORT_ORDER NUMBER(19,0) NOT NULL UNIQUE,
    LATE_RESTRICTED NUMBER(19,0) NOT NULL,
    RETURN_LOAD_BY VARCHAR2(30 CHAR)
);

CREATE TABLE VD_STATION (
    ID VARCHAR2(30 CHAR) PRIMARY KEY,
    BRANCH_ID VARCHAR2(30 CHAR) NOT NULL REFERENCES VD_SITE(ID),
    NAME VARCHAR2(200 CHAR) NOT NULL,
    SORT_ORDER NUMBER(19,0) NOT NULL,
    UNIQUE (ID, BRANCH_ID),
    UNIQUE (BRANCH_ID, SORT_ORDER)
);

CREATE TABLE VD_BUILDING (
    ID VARCHAR2(30 CHAR) PRIMARY KEY,
    SITE_ID VARCHAR2(30 CHAR) NOT NULL REFERENCES VD_SITE(ID),
    STATION_ID VARCHAR2(30 CHAR),
    NAME VARCHAR2(200 CHAR) NOT NULL,
    FOREIGN KEY (STATION_ID, SITE_ID) REFERENCES VD_STATION(ID, BRANCH_ID)
);

CREATE TABLE VD_VEHICLE (
    ID VARCHAR2(30 CHAR) PRIMARY KEY,
    NAME VARCHAR2(200 CHAR) NOT NULL,
    POOL VARCHAR2(30 CHAR) NOT NULL,
    SIZE_CLASS VARCHAR2(30 CHAR),
    HOME_SITE VARCHAR2(30 CHAR) REFERENCES VD_SITE(ID),
    CURRENT_SITE VARCHAR2(30 CHAR) REFERENCES VD_SITE(ID),
    LENGTH_CM NUMBER(24,9) NOT NULL,
    WIDTH_CM NUMBER(24,9) NOT NULL,
    HEIGHT_CM NUMBER(24,9) NOT NULL,
    VOLUME NUMBER(24,9) NOT NULL,
    WEIGHT_LIMIT NUMBER(24,9) NOT NULL,
    SEATS NUMBER(19,0) NOT NULL,
    SORT_ORDER NUMBER(19,0) NOT NULL,
    CHECK (POOL IN ('LOGI','BIZ'))
);

CREATE TABLE VD_DRIVER (
    ID VARCHAR2(30 CHAR) PRIMARY KEY,
    NAME VARCHAR2(200 CHAR) NOT NULL,
    POOL VARCHAR2(30 CHAR) NOT NULL,
    HOME_SITE VARCHAR2(30 CHAR) REFERENCES VD_SITE(ID),
    CURRENT_SITE VARCHAR2(30 CHAR) REFERENCES VD_SITE(ID),
    SORT_ORDER NUMBER(19,0) NOT NULL
);

CREATE TABLE VD_CARGO_CATEGORY (
    CODE VARCHAR2(30 CHAR) PRIMARY KEY,
    NAME VARCHAR2(200 CHAR) NOT NULL,
    FACTOR NUMBER(24,9) NOT NULL CHECK (FACTOR > 0),
    ACTIVE NUMBER(19,0) NOT NULL CHECK (ACTIVE IN (0,1)),
    SORT_ORDER NUMBER(19,0) NOT NULL
);

CREATE TABLE VD_CONFIG (
    KEY_NAME VARCHAR2(30 CHAR) PRIMARY KEY,
    NUM_VALUE NUMBER(24,9) NOT NULL
);

CREATE TABLE VD_REG_SHIFT (
    ID VARCHAR2(30 CHAR) PRIMARY KEY,
    BRANCH_ID VARCHAR2(30 CHAR) NOT NULL REFERENCES VD_SITE(ID),
    LABEL VARCHAR2(200 CHAR) NOT NULL,
    DEPART_MINUTE NUMBER(19,0) NOT NULL CHECK (DEPART_MINUTE BETWEEN 0 AND 1439),
    SORT_ORDER NUMBER(19,0) NOT NULL,
    VEHICLE_ID VARCHAR2(30 CHAR) NOT NULL REFERENCES VD_VEHICLE(ID),
    DRIVER_ID VARCHAR2(30 CHAR) NOT NULL REFERENCES VD_DRIVER(ID),
    UNIQUE (ID, BRANCH_ID),
    UNIQUE (BRANCH_ID, DEPART_MINUTE)
);

CREATE TABLE VD_REG_TRIP (
    SERVICE_DATE DATE NOT NULL,
    SHIFT_ID VARCHAR2(30 CHAR) NOT NULL REFERENCES VD_REG_SHIFT(ID),
    VEHICLE_ID VARCHAR2(30 CHAR) NOT NULL REFERENCES VD_VEHICLE(ID),
    DRIVER_ID VARCHAR2(30 CHAR) NOT NULL REFERENCES VD_DRIVER(ID),
    PRIMARY KEY (SERVICE_DATE, SHIFT_ID)
);

CREATE TABLE VD_REG_APP (
    ID NUMBER(19,0) PRIMARY KEY,
    APP_NO VARCHAR2(30 CHAR) NOT NULL UNIQUE,
    SUBMIT_SEQ NUMBER(19,0) NOT NULL UNIQUE,
    APPLICANT VARCHAR2(200 CHAR) NOT NULL,
    BRANCH_ID VARCHAR2(30 CHAR) NOT NULL REFERENCES VD_SITE(ID),
    PICK_STATION_ID VARCHAR2(30 CHAR) NOT NULL,
    DROP_STATION_ID VARCHAR2(30 CHAR) NOT NULL,
    PICK_BUILDING VARCHAR2(200 CHAR),
    DROP_BUILDING VARCHAR2(200 CHAR),
    RECV_MODE VARCHAR2(30 CHAR) NOT NULL,
    SERVICE_DATE DATE NOT NULL,
    EXPECTED_MINUTE NUMBER(19,0),
    LOAD_MIN NUMBER(19,0) NOT NULL CHECK (LOAD_MIN >= 0),
    UNLOAD_MIN NUMBER(19,0) NOT NULL CHECK (UNLOAD_MIN >= 0),
    RECIPIENT_UNIT VARCHAR2(200 CHAR),
    RECIPIENT_NAME VARCHAR2(200 CHAR),
    RECIPIENT_PHONE VARCHAR2(200 CHAR),
    AGENT_NAME VARCHAR2(200 CHAR),
    AGENT_PHONE VARCHAR2(200 CHAR),
    STATUS VARCHAR2(30 CHAR) NOT NULL,
    SHIFT_ID VARCHAR2(30 CHAR),
    ARRIVAL_MINUTE NUMBER(19,0),
    EXPECT_DIFF_MIN NUMBER(19,0),
    NOTE VARCHAR2(2000 CHAR),
    FAILURE_REASON VARCHAR2(30 CHAR),
    INCIDENT VARCHAR2(200 CHAR),
    CREATED_AT TIMESTAMP NOT NULL,
    DELIVERED_AT TIMESTAMP,
    DELIVERED_BY VARCHAR2(200 CHAR),
    MATCH_ATTEMPT NUMBER(19,0) NOT NULL,
    CHECK (RECV_MODE IN ('asap','exact')),
    CHECK (STATUS IN ('submitted','matched','unscheduled','delivered')),
    CHECK (EXPECTED_MINUTE IS NULL OR EXPECTED_MINUTE BETWEEN 0 AND 1439),
    FOREIGN KEY (PICK_STATION_ID, BRANCH_ID) REFERENCES VD_STATION(ID, BRANCH_ID),
    FOREIGN KEY (DROP_STATION_ID, BRANCH_ID) REFERENCES VD_STATION(ID, BRANCH_ID),
    FOREIGN KEY (SHIFT_ID, BRANCH_ID) REFERENCES VD_REG_SHIFT(ID, BRANCH_ID),
    FOREIGN KEY (SERVICE_DATE, SHIFT_ID) REFERENCES VD_REG_TRIP(SERVICE_DATE, SHIFT_ID),
    CHECK ((STATUS IN ('matched','delivered') AND SHIFT_ID IS NOT NULL) OR (STATUS IN ('submitted','unscheduled') AND SHIFT_ID IS NULL))
);

CREATE TABLE VD_REG_ITEM (
    APPLICATION_ID NUMBER(19,0) NOT NULL REFERENCES VD_REG_APP(ID),
    LINE_NO NUMBER(19,0) NOT NULL,
    NAME VARCHAR2(200 CHAR) NOT NULL,
    LENGTH_CM NUMBER(24,9) NOT NULL CHECK (LENGTH_CM > 0),
    WIDTH_CM NUMBER(24,9) NOT NULL CHECK (WIDTH_CM > 0),
    HEIGHT_CM NUMBER(24,9) NOT NULL CHECK (HEIGHT_CM > 0),
    CATEGORY VARCHAR2(30 CHAR) NOT NULL,
    QTY NUMBER(19,0) NOT NULL CHECK (QTY > 0),
    WEIGHT NUMBER(24,9) NOT NULL CHECK (WEIGHT >= 0),
    PRIMARY KEY (APPLICATION_ID, LINE_NO)
);

CREATE TABLE VD_REG_MATCH_STEP (
    APPLICATION_ID NUMBER(19,0) NOT NULL REFERENCES VD_REG_APP(ID),
    ATTEMPT NUMBER(19,0) NOT NULL,
    STEP_NO NUMBER(19,0) NOT NULL,
    CODE VARCHAR2(30 CHAR) NOT NULL,
    MESSAGE VARCHAR2(2000 CHAR) NOT NULL,
    PRIMARY KEY (APPLICATION_ID, ATTEMPT, STEP_NO)
);

CREATE TABLE VD_MAINTENANCE (
    ID NUMBER(19,0) PRIMARY KEY,
    VEHICLE_ID VARCHAR2(30 CHAR) NOT NULL REFERENCES VD_VEHICLE(ID),
    FROM_DATE DATE NOT NULL,
    TO_DATE DATE NOT NULL,
    REASON VARCHAR2(200 CHAR),
    CHECK (FROM_DATE <= TO_DATE)
);

CREATE TABLE VD_DRIVER_LEAVE (
    ID NUMBER(19,0) PRIMARY KEY,
    DRIVER_ID VARCHAR2(30 CHAR) NOT NULL REFERENCES VD_DRIVER(ID),
    LEAVE_DATE DATE NOT NULL,
    FROM_MINUTE NUMBER(19,0) NOT NULL,
    TO_MINUTE NUMBER(19,0) NOT NULL,
    LEAVE_TYPE VARCHAR2(200 CHAR),
    CHECK (FROM_MINUTE < TO_MINUTE)
);

CREATE TABLE VD_REST_HOUSE (
    ID VARCHAR2(30 CHAR) PRIMARY KEY,
    NAME VARCHAR2(200 CHAR) NOT NULL
);

CREATE TABLE VD_TRAVEL_TIME (
    FROM_ID VARCHAR2(30 CHAR) NOT NULL,
    TO_ID VARCHAR2(30 CHAR) NOT NULL,
    SIZE_CLASS VARCHAR2(30 CHAR) NOT NULL,
    MINUTES NUMBER(19,0) NOT NULL CHECK (MINUTES >= 0),
    PRIMARY KEY (FROM_ID, TO_ID, SIZE_CLASS)
);

CREATE TABLE VD_DRIVER_BREAK (
    AFTER_DRIVE_MIN NUMBER(19,0) PRIMARY KEY,
    KIND VARCHAR2(200 CHAR) NOT NULL,
    COST_MIN NUMBER(19,0) NOT NULL
);

CREATE TABLE VD_MIN_TRIP_DAYS (
    SIZE_CLASS VARCHAR2(30 CHAR) NOT NULL,
    SITE_ID VARCHAR2(30 CHAR) NOT NULL REFERENCES VD_SITE(ID),
    DAYS NUMBER(19,0) NOT NULL,
    PRIMARY KEY (SIZE_CLASS, SITE_ID)
);

CREATE TABLE VD_BIZ_PLACE (
    NAME VARCHAR2(200 CHAR) PRIMARY KEY,
    SITE_ID VARCHAR2(30 CHAR) REFERENCES VD_SITE(ID),
    IS_TRANSFER NUMBER(19,0) NOT NULL
);

CREATE TABLE VD_BIZ_TRAVEL (
    ORIGIN VARCHAR2(200 CHAR) NOT NULL REFERENCES VD_BIZ_PLACE(NAME),
    DESTINATION VARCHAR2(200 CHAR) NOT NULL REFERENCES VD_BIZ_PLACE(NAME),
    MINUTES NUMBER(19,0) NOT NULL,
    PRIMARY KEY (ORIGIN, DESTINATION)
);

CREATE INDEX IX_REG_APP_SHIFT ON VD_REG_APP (SERVICE_DATE, SHIFT_ID, STATUS);

CREATE INDEX IX_REG_APP_BRANCH ON VD_REG_APP (BRANCH_ID, STATUS, SUBMIT_SEQ);

CREATE INDEX IX_REG_APP_DROP ON VD_REG_APP (DROP_STATION_ID);

CREATE SEQUENCE VD_REG_APP_SEQ START WITH 1 INCREMENT BY 1 NOCYCLE;
